import { BaseCustomWebComponentConstructorAppend, css, html } from "@node-projects/base-custom-webcomponent";
export class MermaidDemoView extends BaseCustomWebComponentConstructorAppend {
    static template = html `<div id="preview"></div>`;
    static style = css `
        :host {
            background: white;
            display: block;
            height: 100%;
            overflow: auto;
            position: relative;
            width: 100%;
        }

        #preview {
            box-sizing: border-box;
            min-height: 100%;
            padding: 24px;
            width: 100%;
        }
    `;
    executeCommand(command) {
    }
    canExecuteCommand(command) {
        return false;
    }
    dispose() {
    }
    async display(serviceContainer, instanceServiceContainer, code, style) {
        const preview = this._getDomElement("preview");
        const mermaid = await import("mermaid");
        const id = "mermaid-preview-" + crypto.randomUUID();
        mermaid.default.initialize({ startOnLoad: false, securityLevel: "strict" });
        const result = await mermaid.default.render(id, code || "flowchart TD\n    A[Node]");
        preview.innerHTML = result.svg;
    }
}
customElements.define("node-projects-mermaid-demo-view", MermaidDemoView);
